import sys
from pathlib import Path
sys.path.insert(0,str(Path('corpus/public/reader/neurips2021-robustness')))
from build_foundations import *
p=Paper('F04')
base=[(r'门控向量Σ有限离散；联合/条件概率来自同一分布。零概率事件贡献0，$0\log0=0$。原输入$X$可连续；有限门控分布不把$X$限制为有限。',r'The gate vector is finite and discrete. Joint and conditional probabilities belong to one law, with zero-mass events contributing zero and $0\log0=0$. The original input may be continuous; finiteness of the gate law does not restrict the input domain.')]
a=p.issue('transformation-prefix-direction','B.2第三条原不等号方向错误','The third inequality in B.2 has the wrong direction','false_statement_clause',r'I(X;\Sigma_{1:l};Y)\ge I(X;\Sigma_{1:l+1};Y)','formal PDF14 B.2 third bullet before Eq.(10)',r'$X\in\{-1,1\}$等概率，$Y=1_{X=1}$；第1层ReLU输入$X+2$始终正，$\Sigma_1=1$，输出$t_1=X+2$；第2层输入$t_1-2=X$，$\Sigma_2=Y$。所以左边0、右边$\log2>0$。所有门均由确定性ReLU层产生。Eq.(11)算出差$-\log2\le0$，本身正确。',r'Let $X$ be uniform on $\{-1,1\}$ and $Y=1_{X=1}$. The first ReLU preactivation is $X+2>0$, so its gate is constant and its output is $t_1=X+2$. The second preactivation is $t_1-2=X$, so its gate equals $Y$. The displayed left side is zero and the right side is $\log2>0$. These are actual deterministic ReLU gates. Equation (11) correctly computes a nonpositive difference.','只否定附录该子句；正文Property2的increase叙述正确，不能改≥后声称修原证明。','Only this appendix clause is refuted. The main-text increase statement remains valid; changing the inequality would change the target.',['transformation-prefix-coinfo'])
b=p.issue('transformation-kde-discrete-bound','Eq.(25)不是离散门控熵的上界','Equation (25) is not an upper bound on discrete gate entropy','false_statement_clause',r'H(\Sigma_l)\le -n^{-1}\sum_j\log[n^{-1}\sum_k e^{-\|\sigma_j-\sigma_k\|^2/(2\sigma_0^2)}]','formal PDF17 Eq.(25)',r'两个等概率不同二值门向量，距离平方$d^2>0$、带宽$\sigma_0^2>0$。左边$\log2$，右边$\log2-\log(1+e^{-d^2/(2\sigma_0^2)})<\log2$。确定性ReLU门$1_{X>0}$可实现这两个状态。连续加噪特征的MI界不能原封不动成为离散Σ熵界。',r'Two distinct equally likely binary gate vectors at squared distance $d^2>0$ have entropy $\log2$. The displayed right side is $\log2-\log(1+e^{-d^2/(2\sigma_0^2)})<\log2$ for every positive bandwidth. A deterministic ReLU gate $1_{X>0}$ realizes the example. A bound for a continuously noise-smoothed feature cannot be reused as a bound on the discrete gate entropy.','Eq25及依赖该上界的Eq26/27需单列；实验估计值仍是原经验结果。','Equation (25) and bounds derived by that substitution require separate qualification; numerical estimates remain empirical results.',['transformation-kde-gates','transformation-kde-randomness','transformation-kde-coinfo'])
c=p.issue('transformation-kde-class-weights','Eq.(27)后的类别权重未归一化','Class weights after Equation (27) are not normalized','definition_error',r'p_m=n_m/M','formal PDF18 after Eq.(27)',r'共有$n=\sum_m n_m$样本而$M$是类别数，故$\sum_m p_m=n/M$一般不是1。PDF17 Eq24此前定义$p_l=P_l/P$正确。',r'There are $n=\sum_m n_m$ samples and $M$ classes, so the displayed weights sum to $n/M$, generally not one. The earlier definition $p_l=P_l/P$ on page 17 is normalized.','这是原定义错误，另列而不替换原式。','The original definition is retained and flagged.',['transformation-kde-coinfo'])
d=p.issue('transformation-kde-equality','Eq.(24)把熵估计替换写成精确等号','Equation (24) presents an entropy estimate as an equality','unjustified_equality',r'I(\widehat T;Y)=\widehat H(\widehat T)-\widehat H(\widehat T\mid Y)','formal PDF17 Eq.(24)',r'Eq23只给$I(\widehat T;X)$的上界，并未给两个精确熵；两项上界相减不保证仍为MI上界，也不成为精确等式。','Equation (23) supplies a bound, not two exact entropies. Subtracting two upper bounds need not bound their difference and cannot produce an exact equality.','保留原估计定义；不以精确MI定理角色交付。','Retain the estimator, without representing it as an exact mutual-information theorem.',['transformation-kde-labels'])
e=p.issue('transformation-ebm-domain','二值门控的Langevin偏导未定义','Langevin derivatives are unspecified on binary gates','domain_issue',r'\partial q(\sigma_l^d)/\partial\sigma_l^d','formal PDF19 Eq.(37)',r'Eq32将$q$定义于二值集合，未给连续可微延拓；Eq37要求该偏导且高斯步会离开二值集合。原公式的连续采样实现条件不充分。','Equation (32) defines the prior only on binary states. Equation (37) differentiates it and applies a Gaussian step that leaves that state space; no differentiable continuous extension is specified.','有限离散EBM归一化与参数MLE导数可独立成立；状态Langevin推导不能当作二值精确定理。','Finite-state EBM normalization and parameter likelihood derivatives remain valid; the state-space Langevin formula is not an exact binary-state theorem.',['transformation-ebm-langevin'])
f=p.issue('transformation-activation-average','平均激活率不决定边际熵总和','The average activation rate does not determine the marginal entropy sum','unquantified_approximation',r'C_l=\sum_d h(a_{l,d})','formal PDF5 after Eq.(2); PDF16 B.4',r'两个维度激活率$(1/2,1/2)$与$(0,1)$均平均1/2，但$C_l$分别$2\log2$与0。逐坐标激活率相近才控制对应边际熵；平均值收敛不够。',r'Rates $(1/2,1/2)$ and $(0,1)$ both average to one half, but their marginal entropy sums are $2\log2$ and zero. Similar coordinate-wise rates can control the sum; convergence of their average alone does not.','Eq2精确恒等式正确，随后粗略constant解释分开。','The exact identity in Equation (2) is valid; its subsequent approximate interpretation is separate.',['transformation-total-correlation','transformation-conditional-correlation'])
def add(id,zh,en,label,tex,pg,steps,**kw):return p.result(id,zh,en,label,tex,[('formal',pg,label)],steps,assumptions=base,**kw)
add('transformation-gating-affine','固定门控下的仿射变换','Affine transformation at fixed gates','Eq.(1); Appendix A',r'z=W_{L+1}\sigma_LW_L\cdots\sigma_1W_1x+b',[3,13],[(r'固定本次输入所触发的门矩阵。ReLU门取正输入为1、否则0；dropout门表示保留；max-pooling每输出位置选择一个最大输入。','Fix the gate matrices triggered by the current input. ReLU gates select positive preactivations, dropout gates retain coordinates, and each max-pooling output selects one maximizer.',''),(r'逐层展开$h_{l+1}=W_{l+1}\sigma_lh_l+b_{l+1}$，归纳得到输入的线性系数积与所有偏置的传递和。门控区域内这些矩阵固定；跨区域允许改变。',r'Expand $h_{l+1}=W_{l+1}\sigma_lh_l+b_{l+1}$ recursively. Induction gives the product multiplying the input and the sum of propagated biases. These coefficients are fixed within the gate region and may vary across regions.',r'W=W_{L+1}\sigma_LW_L\cdots\sigma_1W_1')])
add('transformation-entropy-chain','门控熵的逐层链式展开','Chain expansion of gate entropy','Section3 entropy decomposition',r'H(\Sigma)=\sum_{l=1}^L H(\Sigma_l\mid\Sigma_{1:l-1})',[4],[(r'对有限联合表写$p(a,b)=p(a)p(b\mid a)$。正质量项用$\log p(a,b)=\log p(a)+\log p(b\mid a)$；$p(a)=0$时整行联合质量为0，不必定义该条件分布。',r'For a finite joint table, write $p(a,b)=p(a)p(b\mid a)$. Split the logarithm on positive-mass terms. A zero-mass marginal has an entirely zero row and needs no conditional law.',r'H(A,B)=H(A)+H(B\mid A)',['Harsanyi.Entropy.entropy_chain']),(r'对门向量逐次应用二变量链式规则，直到最后一层。非负条件熵表明增加门坐标不会降低联合熵。','Apply the two-variable chain rule successively along the gate vector. Nonnegative conditional entropy shows that adding gate coordinates cannot decrease joint entropy.','',['Harsanyi.Entropy.conditional_entropy_nonneg'])],lean=['Harsanyi.Entropy.entropy_chain','Harsanyi.Entropy.conditional_entropy_nonneg'])
add('transformation-deterministic-input','确定性门控时输入互信息等于门熵','Input mutual information equals gate entropy for deterministic gates','Section3 I(X;Σ)',r'H(\Sigma\mid X)=0,\quad I(X;\Sigma)=H(\Sigma)',[4,13],[(r'无额外采样或dropout时，每个$x$唯一决定门向量$\sigma(x)$。给定$x$的门条件分布是单点分布，熵为0；对$x$平均仍为0。','Without additional sampling or dropout, every input determines one gate vector. Its conditional gate law is a point mass and has zero entropy; averaging preserves zero.',''),(r'代入$I(X;\Sigma)=H(\Sigma)-H(\Sigma\mid X)$。这只对有限门变量取熵，允许原输入为连续向量。',r'Substitute into $I(X;\Sigma)=H(\Sigma)-H(\Sigma\mid X)$. Only the finite gate variable requires entropy, so the input may remain continuous.','')])
add('transformation-coinfo-nonnegative','Property1：确定性门的三元信息非负','Property 1: nonnegative three-way information for deterministic gates','Property1; B.1 Eqs.(6)–(7)',r'I(X;\Sigma;Y)=I(\Sigma;Y)\ge0',[4,13],[(r'按原定义交换熵差项，$I(X;\Sigma;Y)=I(\Sigma;Y)-I(\Sigma;Y\mid X)$。给定输入后Σ恒定，即使Y有噪声也有$I(\Sigma;Y\mid X)=0$。',r'Rearrange the defining entropy differences to obtain $I(X;\Sigma;Y)=I(\Sigma;Y)-I(\Sigma;Y\mid X)$. Conditional on the input, the gate is constant, so the last information is zero even when the label is noisy.',r'I(X;\Sigma;Y)=(H(Y)-H(Y\mid\Sigma))-(H(Y\mid X)-H(Y\mid X,\Sigma))'),(r'对门和分类标签的有限联合分布，$I(\Sigma;Y)=D(p_{\Sigma Y}\Vert p_\Sigma p_Y)$。正质量联合项的两个边缘必正；由$\log t\le t-1$求和得Gibbs不等式，允许零边缘行。',r'For the finite gate-label joint law, mutual information equals divergence from the product marginals. Positive joint mass has positive marginals. Summing $\log t\le t-1$ proves Gibbs inequality without requiring full support.','',['Harsanyi.Entropy.mutual_information_eq_divergence','Harsanyi.Entropy.mutual_information_nonneg'])],author_pages=[('formal',[13])],author_math=[r'I(X;\Sigma;Y)=(H(Y)-H(Y\mid X))-(H(Y\mid\Sigma)-H(Y\mid X,\Sigma))',r'I(X;\Sigma;Y)=H(Y)-H(Y\mid\Sigma)\ge0'],lean=['Harsanyi.Entropy.mutual_information_nonneg'])
# Separate every local proof bullet; the wrong appendix statement is preserved.
for id,zh,en,label,tex,pg,form,z,e,ln in [
('transformation-prefix-entropy','Property2：前缀门联合熵增加','Property 2: prefix gate entropy increases','B.2 first bullet Eq.(8)',r'H(\Sigma_{1:l})\le H(\Sigma_{1:l+1})',[4,13],r'H(\Sigma_{1:l})-H(\Sigma_{1:l+1})=-H(\Sigma_{l+1}\mid\Sigma_{1:l})\le0',r'链式规则将新旧联合熵差化为新增门的条件熵；条件概率位于[0,1]，$-p\log p\ge0$。零质量行贡献0。',r'The chain rule identifies the increase as the added gate conditional entropy. Conditional masses lie in [0,1], so $-p\log p$ is nonnegative. Zero rows contribute zero.',['Harsanyi.Entropy.entropy_marginal_le']),
('transformation-prefix-input','Property2：前缀门输入互信息增加','Property 2: prefix gate input information increases','B.2 second bullet Eq.(9)',r'I(X;\Sigma_{1:l})\le I(X;\Sigma_{1:l+1})',[4,13],r'I(X;\Sigma_{1:l})-I(X;\Sigma_{1:l+1})=H(\Sigma_{1:l})-H(\Sigma_{1:l+1})\le0','原无额外随机性的假设使两组门给定X均为确定性，两个条件熵为0。故比较化为前一条联合熵比较；原Σ1重复下标按Eq9实际对象辨认。','The original absence of extra randomness makes both gate groups deterministic given X, so both conditional entropies vanish. The comparison reduces to joint entropy monotonicity; the repeated Σ1 subscript is identified by Equation (9).',[]),
('transformation-suffix-entropy','Property3：剩余门联合熵递减','Property 3: remaining gate entropy decreases','B.3 first bullet Eq.(12)',r'H(\Sigma_{l:L})\ge H(\Sigma_{l+1:L})',[4,14],r'H(\Sigma_{l:L})-H(\Sigma_{l+1:L})=H(\Sigma_l\mid\Sigma_{l+1:L})\ge0','先把Σl视作新增有限坐标，其余后缀视为条件。链式规则和条件熵非负给出比较，不依赖层间独立。','Treat Σl as the added finite coordinate and the suffix as the conditioning variable. The chain rule and nonnegative conditional entropy give the comparison, with no layer independence assumption.',['Harsanyi.Entropy.entropy_marginal_le']),
('transformation-suffix-input','Property3：中间特征的剩余门互信息递减','Property 3: remaining-gate input information decreases','B.3 second bullet Eq.(13)',r'I(T_{l-1};\Sigma_{l:L})\ge I(T_l;\Sigma_{l+1:L})',[4,14],r'I(T_{l-1};\Sigma_{l:L})-I(T_l;\Sigma_{l+1:L})=H(\Sigma_{l:L})-H(\Sigma_{l+1:L})\ge0','在原确定性逐层网络中，Tl−1决定所有剩余门、Tl决定再后一层的门；相应给定特征的条件熵都为0。代入定义后应用后缀联合熵比较。','In the original deterministic layered network, each feature determines its downstream gates. Both conditional entropies vanish. Substitute the definition and use the suffix joint entropy comparison.',[]),
('transformation-suffix-coinfo','Property3：推理三元信息递减','Property 3: remaining-gate inference information decreases','B.3 third bullet Eqs.(14)–(15)',r'I(T_{l-1};\Sigma_{l:L};Y)\ge I(T_l;\Sigma_{l+1:L};Y)',[4,14],r'I(T_{l-1};\Sigma_{l:L};Y)-I(T_l;\Sigma_{l+1:L};Y)=I(\Sigma_l;Y\mid\Sigma_{l+1:L})\ge0','确定性门将两项三元信息化为门与Y的互信息；相减后是给定后缀的Σl/Y条件MI。每个正质量后缀事件上应用有限Gibbs不等式，再按事件概率平均。','Determinism reduces both three-way terms to gate-label mutual information. Their difference is conditional mutual information between the removed gate and Y given the suffix. Apply finite Gibbs inequality on each positive-mass suffix event and average.',[])]:
 add(id,zh,en,label,tex,pg,[(z,e,form,ln)],author_pages=[('formal',[pg[-1]])],author_math=[form],lean=ln)
add('transformation-prefix-coinfo','B.2：三元信息方向错误的原子句','B.2: the original reversed three-way inequality','B.2 third bullet Eqs.(10)–(11)',r'I(X;\Sigma_{1:l};Y)\ge I(X;\Sigma_{1:l+1};Y)',[14],[(r'保留原≥。构造$X$为均匀±1，$Y=1_{X=1}$；先ReLU$(X+2)$后ReLU$(T_1-2)$，门分别为恒1和Y。前缀门不提供标签信息，而新增门完全确定标签。','Retain the original ≥. Let X be uniform ±1 and Y its positive-sign indicator. Apply ReLU to X+2, then to T1−2. The first gate is constant and the second is Y. The old prefix provides no label information, while the added gate determines the label.',r'I(X;\Sigma_1;Y)=0,\quad I(X;\Sigma_1,\Sigma_2;Y)=\log2>0'),(r'原Eq11通过条件MI非负确实得到差≤0，与≥陈述冲突。正文Property2的增加方向成立；附录子句不能靠换号“修证明”。','Equation (11) correctly gives a nonpositive difference by conditional information nonnegativity, contradicting the displayed ≥. The main-text increase direction remains valid; changing the sign would change the appendix claim.','')],author_pages=[('formal',[14])],author_math=[r'I(X;\Sigma_{1:l};Y)=H(Y)-H(Y\mid\Sigma_{1:l})',r'I(X;\Sigma_{1:l};Y)-I(X;\Sigma_{1:l+1};Y)=-I(\Sigma_{l+1};Y\mid\Sigma_{1:l})\le0'],issues=[a],role='counterexample',assessment='false_original_clause')
for id,zh,en,label,tex,pg,math,steps,iss in [
('transformation-total-correlation','复杂度与总相关的精确恒等式','Exact entropy and total-correlation identity','Eq.(2); B.4 Eq.(16)',r'H(\Sigma_l)+TC(\Sigma_l)=\sum_d H(\Sigma_l^d)=C_l',[5,15],[r'TC(\Sigma_l)=\sum_\sigma p(\sigma)\log\frac{p(\sigma)}{\prod_d p_d(\sigma_d)}',r'H(\Sigma_l)+TC(\Sigma_l)=-\sum_\sigma p(\sigma)\log\prod_d p_d(\sigma_d)=\sum_d H(\Sigma_l^d)=C_l'],[(r'正质量联合状态的每个边缘质量必正，故可展开乘积对数。把KL与联合熵相加，联合$p\log p$项抵消；每个坐标的对数项按其他坐标求和成为边缘概率。','Every positive-mass joint state has positive marginal masses, so its product logarithm can be split. Adding divergence to joint entropy cancels the joint log term; summing out other coordinates gives each marginal entropy.',''),(r'二值坐标的边缘熵是$h(a_d)=-a_d\log a_d-(1-a_d)\log(1-a_d)$，端点按0log0约定。只有完整逐坐标激活率固定时Cl严格固定；平均率相等不够。',r'Each binary marginal entropy is $h(a_d)=-a_d\log a_d-(1-a_d)\log(1-a_d)$, with the zero-mass convention at endpoints. Fixed coordinate-wise rates fix Cl; an equal average rate alone does not.','')],[f]),
('transformation-input-correlation','输入MI与总相关的恒等式','Input information and total correlation identity','Eq.(3) first; B.4 Eq.(17)',r'I(X;\Sigma_l)+TC(\Sigma_l)=C_l-H(\Sigma_l\mid X)',[5,15],[r'I(X;\Sigma_l)+TC(\Sigma_l)=H(\Sigma_l)-H(\Sigma_l\mid X)+TC(\Sigma_l)=C_l-H(\Sigma_l\mid X)'],[(r'对上一恒等式减去$H(\Sigma_l\mid X)$并代入MI定义。随机网络仍保留该残差；确定性网络残差才为0。',r'Subtract $H(\Sigma_l\mid X)$ from the preceding identity and insert the mutual-information definition. The residual remains for a random network and vanishes for deterministic gates.','')],[]),
('transformation-conditional-correlation','条件总相关与推理复杂度','Conditional total correlation and inference complexity','Eq.(3) second; B.4 Eqs.(18)–(22)',r'I(X;\Sigma_l;Y)+TC(\Sigma_l)-TC(\Sigma_l\mid Y)=C_l-C_{l\mid Y}-H(\Sigma_l\mid X)+H(\Sigma_l\mid X,Y)',[5,15,16],[r'I(X;\Sigma_l;Y)=I(X;\Sigma_l)-I(X;\Sigma_l\mid Y)',r'TC(\Sigma_l\mid Y)=\sum_y p(y)D(p(\sigma_l\mid y)\Vert\prod_d p(\sigma_l^d\mid y))',r'I(X;\Sigma_l\mid Y)+TC(\Sigma_l\mid Y)=C_{l\mid Y}-H(\Sigma_l\mid X,Y)',r'I(X;\Sigma_l)+TC(\Sigma_l)=C_l-H(\Sigma_l\mid X)',r'I(X;\Sigma_l;Y)=(C_l-C_{l\mid Y})-(TC(\Sigma_l)-TC(\Sigma_l\mid Y))\quad\text{under deterministic gates}'],[(r'在每个正质量标签事件上重复总相关恒等式并按p(y)平均，得到$H(\Sigma_l\mid Y)+TC(\Sigma_l\mid Y)=\sum_dH(\Sigma_l^d\mid Y)=C_{l\mid Y}$。零概率标签事件贡献0。',r'Repeat the total-correlation identity on each positive-mass label event and average. This gives $H(\Sigma_l\mid Y)+TC(\Sigma_l\mid Y)=\sum_dH(\Sigma_l^d\mid Y)=C_{l\mid Y}$. Zero-probability labels contribute zero.',''),(r'分别代入无条件MI和条件MI，作差得到所列完整恒等式。确定性时两个输入条件门熵均0。原文相似激活率使Cl|Y相似是经验近似，Appendix C自身列出例外，不能由Cl相似推出。','Insert unconditional and conditional information and subtract to obtain the full identity. Under deterministic gates both input-conditional gate entropies vanish. Similar Cl|Y under similar activation rates is empirical; Appendix C itself records exceptions, and similar Cl does not imply it.','')],[f])]:
 add(id,zh,en,label,tex,pg,steps,author_pages=[('formal',[n for n in pg if n>=15])],author_math=math,issues=iss)
# All KDE/displayed bounds are retained as distinct targets, with their scope.
for id,zh,en,label,tex,pg,z,e,iss in [
('transformation-kde-input','连续加噪特征的外引KDE界','Externally cited KDE bound for a noise-smoothed feature','Appendix E Eq.(23)',r'I(\widehat T;X)\le-\frac1P\sum_i\log\frac1P\sum_j e^{-\|t_i-t_j\|^2/(2\sigma_0^2)}',[16,17],r'原外引对象是$\widehat T=T+\epsilon$、高斯噪声方差σ0²>0、有限经验输入索引；不是未加噪离散门熵。保留原外引及其本地无证明状态。','The cited object is a Gaussian-noise-smoothed feature with positive noise variance and a finite empirical input index, rather than the entropy of an unsmoothed discrete gate. The external citation and absence of a local proof are retained.',[]),
('transformation-kde-labels','Eq24：标签MI估计','Equation (24): label-information estimate','Appendix E Eq.(24)',r'I(\widehat T;Y)=\widehat H(\widehat T)-\sum_l p_l\widehat H(\widehat T\mid Y=l)',[17],'原展示式把全样本核对数平均减去按标签分组的核对数平均。真实MI的熵差定义成立；替换估计的精确等号没有本地证明，上界相减不足。','The displayed estimator subtracts class-wise kernel log averages from the all-sample average. The true entropy-difference definition is valid, but replacing both entropies by estimates has no local equality proof and subtracting upper bounds is insufficient.',[d]),
('transformation-kde-gates','Eq25：离散门熵上界反例','Equation (25): counterexample to the gate-entropy bound','Appendix E Eq.(25)',r'H(\Sigma_l)\le-\frac1n\sum_j\log\frac1n\sum_k e^{-\|\sigma_j-\sigma_k\|^2/(2\sigma_0^2)}',[17],r'两个等概率不同门状态的真实熵log2。核和包含自项1与正的跨状态项ε，估计为log2−log(1+ε)，严格更小。原带宽κVarΣ为正，此反例不靠零方差。',r'Two equally probable distinct gate states have entropy log2. The kernel sum includes the self term 1 and a positive cross-state term ε, giving log2−log(1+ε), strictly smaller. The original bandwidth κVarΣ is positive, so this does not use a zero-variance degeneracy.',[b]),
('transformation-kde-randomness','移除采样的门控估计并非一般MI界','Removing sampling does not supply a general information bound','Appendix E Eq.(26)',r'I(X;\Sigma_l)\le-\frac1n\sum_j\log\frac1n\sum_k e^{-\|\widehat\sigma_j-\widehat\sigma_k\|^2/(2\sigma_0^2)}',[17],'原widehatΣ通过移除采样得到，原文未规定随机层移除算子或与原条件MI的比较条件。即使无随机性，它退化Eq25的错误界；保留源公式，不添加前提使其冒充原目标。','The hatted gates are obtained by removing sampling, without a specified removal operator or a comparison theorem for the original conditional information. Even in the deterministic case the expression reduces to the false bound in Equation (25). The original formula is retained without adding premises.',[b]),
('transformation-kde-coinfo','Eq27：三元信息的KDE界问题','Equation (27): problems with the three-way KDE bound','Appendix E Eq.(27)',r'I(X;\Sigma_l;Y)\le\widehat H(\Sigma_l)-\sum_m p_m\widehat H(\Sigma_l\mid Y=m)-I(\Sigma_l;Y\mid X)',[18],'原式先减条件MI再减类别估计。前两估计相减没有一般上界保证；原pm=nm/M也未归一化。选Σ=Y等概率二值时条件熵0而全熵估计小于log2，直接否定该上界。','The first two entropy estimates do not generally bound their difference, and the source pm=nm/M is not normalized. Taking the gate equal to an equally likely binary label gives zero class entropy and a global estimate below log2, directly refuting the bound.',[b,c,d]),
('transformation-kde-tc','Eq29：总相关的核比估计','Equation (29): kernel-ratio estimate for total correlation','Appendix E Eqs.(28)–(29)',r'TC(\Sigma_l)\le\frac1P\sum_i\log\frac{\sum_j e^{-\|\sigma_i-\sigma_j\|^2/(2\sigma_0^2)}}{\sum_j e^{-\|\sigma_i-\widehat\sigma_j\|^2/(2\sigma_0^2)}}',[18],'原外引启发的估计将独立边缘乘积分布用合成样本近似。有限随机合成样本及核近似不必保持原KL大小，本篇没有支持该确定性≤的误差条件或证明。保留为未经证明的估计界。','The estimator approximates the product-marginal distribution with synthesized samples. Finite random samples and kernel approximations need not preserve the KL ordering, and this paper provides no error conditions or proof for the deterministic ≤. It is retained as an unproved estimator bound.',[])]:
 add(id,zh,en,label,tex,pg,[(z,e,tex)],kind='externally_cited_bound' if id.endswith('input') else 'estimator_claim',issues=iss,role='counterexample' if id in ['transformation-kde-gates','transformation-kde-randomness','transformation-kde-coinfo'] else 'scope_analysis',assessment='false_original_bound' if id in ['transformation-kde-gates','transformation-kde-randomness','transformation-kde-coinfo'] else 'external_or_unproved_estimator')
for id,zh,en,label,tex,pg,z,e,math,iss,role in [
('transformation-ebm-normalization','EBM归一化与能量形式','EBM normalization and energy form','Appendix F Eqs.(30)–(33)',r'p_\theta(\sigma)=Z_\theta^{-1}e^{f_\theta(\sigma)}q(\sigma),\ E_\theta=-\log q-f_\theta',[18,19],'有限门状态上将Z定义为加权指数和；q是正规先验且至少一个状态正质量，实f使Z>0。逐项求和p得到1。正q支撑上取负对数得到能量，q=0状态保留零概率、不取log0为实能量。','On finite gate states, Z is the weighted exponential sum. A normalized prior has a positive-mass state, and real f makes Z positive. Summing the model gives one. On positive prior support, taking the negative logarithm gives the energy; zero-prior states retain zero probability without assigning a finite log energy.',[r'L_{complexity}=\sum_l H(\Sigma_l)',r'p_{\theta_f}(\sigma_l)=Z(\theta_f)^{-1}\exp[f(\sigma_l;\theta_f)]q(\sigma_l)',r'Z(\theta_f)=E_q[\exp f]=\int q(\sigma_l)\exp[f(\sigma_l;\theta_f)]d\sigma_l',r'q(\sigma_l)=\prod_d q(\sigma_l^d),\quad q(\sigma_l^d)=\begin{cases}\widehat p&\sigma_l^d=1\\1-\widehat p&\sigma_l^d=0\end{cases}',r'E_{\theta_f}(\sigma_l)=-\log q(\sigma_l)-f(\sigma_l;\theta_f)'],[],'proof'),
('transformation-ebm-mle','参数MLE损失及梯度','Parameter likelihood loss and gradient','Appendix F Eqs.(34)–(36)',r'\nabla_\theta L=E_{p_\theta}[\nabla_\theta f]-n^{-1}\sum_i\nabla_\theta f(\sigma_i)',[19],'负对数似然展开为−经验f均值−经验logq均值+logZ。有限状态且f参数可微时可交换导数与和，dlogZ=Z−1Σqexp(f)df=E_p df；q不依赖参数，故得到梯度。原Eq34最大化loglikelihood，而Eq35把L用作其负号，两处记号方向分开。','Expand the negative log likelihood as minus the empirical f and log-q averages plus log Z. For finitely many states and differentiable parameter scores, differentiate the finite sum to obtain dlog Z=Z−1Σqexp(f)df=E_p df. The prior does not depend on the parameters. Equation (34) maximizes log likelihood, whereas Equation (35) reuses L for its negative; the two optimization signs are distinct.',[r'\widehat\theta_f=\arg\max_{\theta_f}n^{-1}\sum_i\log p_{\theta_f}(\sigma_{l,i})',r'L(\theta_f)=-n^{-1}\sum_i[f(\sigma_{l,i};\theta_f)+\log q(\sigma_{l,i})]+\log Z(\theta_f)',r'\partial_{\theta_f}L=E_{\theta_f}[\partial_{\theta_f}f]-n^{-1}\sum_i\partial_{\theta_f}f(\sigma_{l,i};\theta_f)'],[],'proof'),
('transformation-ebm-langevin','Langevin状态更新的定义域缺口','Domain gap in Langevin state updates','Appendix F Eq.(37)',r'\sigma^{new}=\sigma-\tfrac{\Delta\tau}2\partial_\sigma E+\sqrt{\Delta\tau}\epsilon',[19],'原二值q没有状态导数；高斯扰动也不保持二值集合。若另定义可微连续EBM，链式规则可展开−∂E=∂f+∂logq，但这是额外模型，不能当原二值陈述的修证明。','The original binary prior has no state derivative, and Gaussian noise does not preserve the binary state space. A separately defined smooth continuous EBM permits the chain-rule expansion −dE=df+dlogq, but that would be an additional model rather than a proof of the original binary formula.',[r'\sigma_l^{new}=\sigma_l+\frac{\Delta\tau}2\left[\partial_{\sigma_l}f+\sum_d\frac1{q(\sigma_l^d)}\partial_{\sigma_l^d}q(\sigma_l^d)\right]+\sqrt{\Delta\tau}\epsilon'],[e],'scope_analysis'),
('transformation-ebm-sampling-loss','Monte Carlo梯度与复杂度替代损失','Monte Carlo gradient and surrogate complexity loss','Appendix F Eqs.(38)–(39)',r'\nabla L\approx n^{-1}\sum_i\nabla f(\widetilde\sigma_i)-n^{-1}\sum_i\nabla f(\sigma_i)',[19],'对模型期望用采样平均作近似，原≈保留。冻结拟合参数后−logp的经验均值可代入能量加logZ；它是对拟合模型的交叉熵，只有模型分布与真实门分布相同才等于真实熵。','Replace the model expectation by a sampling average, retaining the source ≈. With fitted parameters frozen, the empirical negative model log probability equals energy plus log Z. This is cross entropy against the fitted model and equals true entropy only when the distributions match.',[r'\partial L\approx n^{-1}\sum_i\partial f(\widetilde\sigma_i)-n^{-1}\sum_i\partial f(\sigma_i)=\partial[n^{-1}\sum_iE(\sigma_i)-n^{-1}\sum_iE(\widetilde\sigma_i)]',r'L_{complexity}=-\sum_lE_{\sigma_l}\log p_{\widehat\theta_f}(\sigma_l)=n^{-1}\sum_{l,i}[E_{\widehat\theta_f}(\sigma_{l,i})+\log Z(\widehat\theta_f)]'],[],'scope_analysis')]:
 add(id,zh,en,label,tex,pg,[(z,e,tex)],author_pages=[('formal',pg)] if id!='transformation-ebm-langevin' else [('formal',[19])],author_math=math,issues=iss,role=role,assessment='valid_with_explicit_differentiability_scope' if id.endswith('mle') else 'domain_issue' if iss else 'estimator_or_exact_definition')
add('transformation-external-and-experiments','外引背景与经验结论范围','External background and empirical claims','Sections1–5; Appendices C,D,G',r'\text{Empirical complexity, robustness, transferability and consistency comparisons}',[1,2,3,6,7,8,9,10,11,12,16,20,21,22],[(r'原外引NP-hard、表达能力/信息瓶颈、KDE与训练正则化背景保留为外引，不算本地作者证明。Figures2–14、Tables1–3与Appendix C/D/G给出训练动态、容量上限、鲁棒性/转移和一致性的具体模型/样本结果；没有把经验趋势升级为所有网络的定理。','The cited complexity, representation, bottleneck, KDE and regularization background remains external rather than local proof. Figures 2–14, Tables 1–3 and Appendices C/D/G report particular models, samples, training dynamics, capacity, robustness, transfer and consistency; empirical trends are not promoted to universal network theorems.','')],kind='empirical_and_external_scope',role='scope_analysis',assessment='empirical_or_external')
